item.content:encoded:
.p-news-ticker a { color: #000000; } /* 記事タイトルの文字色 */

.site-footer {
  color: black;
}



.content .outline {
    border: 1px solid #aaa;
    width: 90%;
    display: block;
    margin: 0 auto;
    position: relative;
}

.outline__title {
    font-weight: bold;
    font-size: 18px;
    border-bottom: solid 2px #333;
}

.outline__title:before {
    font-family: "icomoon";
    content: "\e92f";
    margin-right: 3px;
    font-weight: bold;
}

.content .outline__number {
    display: none;
}

.content .outline__link:before {
    font-family: "icomoon";
    content: "\ea44";
    margin-right: 5px;
}

.content .outline__link {
    color: #333;
    font-size: 15px;
    font-weight: bold;
    border-bottom: dashed 1px #aaa;
}

.outline__list .outline__list-3 .outline__link {
    color: #666;
    font-size: 13px;
    font-weight: normal;
    border-bottom: none;
}

.outline__list .outline__list-3 .outline__link:before {
    display: none;
}

.content .outline__switch + .outline__list-2 li:first-child {
    margin-top: 2rem;
}

.content .outline__toggle:checked + .outline__switch::before {
    content: "[非表示]";
    border: none;
    color: #4682b4;
    font-size: 15px;
    margin-left: 0px;
}

.content .outline__toggle:checked + .outline__switch + .outline__list {
    margin-top: 1rem;
    background: initial;
}

.content .outline__switch::before {
    content: "[表示]";
    border: none;
    color: #4682b4;
    font-size: 15px;
    margin-left: 0px;
}
/* 子ページのタイトル画像部分を非表示にする */
.page-id-145 .p-page-header {
    display: none;
}

.page-id-145 .breadcrumb,
.page-id-145 .breadcrumbs,
.page-id-145 #breadcrumb {
    display: none !important;
}



/* 子ページID:145のタイトルバナー画像を設定 */
.page-id-145 .p-page-header {
    display: block !important; /* ヘッダーを確実に表示 */
    background-image: url('https://www.hellojazzacademy.com/wp-content/uploads/2025/01/%E3%82%A2%E3%82%A4%E3%83%9C%E3%83%AA%E3%83%BC%E3%80%80%E3%82%B9%E3%82%AB%E3%82%A4%E3%83%96%E3%83%AB%E3%83%BC%E3%80%80EC%E3%80%80%E3%82%B7%E3%83%A7%E3%83%83%E3%83%97%E3%80%80%E3%82%A6%E3%82%A7%E3%83%96%E3%82%B5%E3%82%A4%E3%83%88-1.png');
    background-size: cover; /* 画像を全体に拡大 */
    background-position: center; /* 画像を中央寄せ */
    height: 400px; /* 必要に応じて高さを調整 */
}

/* 必要に応じてタイトルや説明文を非表示にする */
.page-id-145 .p-page-header__title,
.page-id-145 .p-page-header__desc,
.page-id-145 .p-page-header__meta {
    display: none !important;
}
/* 子ページID:145のタイトルバナー画像のフィルターを無効化 */
.page-id-145 .p-page-header::before {
    content: none !important; /* フィルターやオーバーレイを削除 */
}

/* フィルター効果を完全に無効化 */
.page-id-145 .p-page-header {
    filter: none !important; /* CSSフィルターを削除 */
    background-blend-mode: normal !important; /* 背景のブレンドモードを通常に設定 */
    opacity: 1 !important; /* 透明度を通常に設定 */
}



@media (max-width: 768px) {
    .page-id-145 .page-header {
        height: 250px; /* モバイル向けの高さ */
    }
}

/* 子ページID:145のパンくずリストを非表示にする */
.page-id-145 .breadcrumb,
.page-id-145 .breadcrumbs,
.page-id-145 .p-breadcrumb,
.page-id-145 #breadcrumb {
    display: none !important;
}

/* ハンバーガーメニュー内の文字色をダークグレーに変更 */
.menu-toggle, 
.menu-toggle a, 
.menu-item a {
    color: #333333 !important; /* ダークグレー */
}

/* ハンバーガーメニューのホバー時の文字色をダークグレーに変更 */
.menu-item a:hover {
    color: #333333 !important;
}

/* 現在表示中のページのメニュー文字色をダークグレーに変更 */
.menu-item.current-menu-item a {
    color: #333333 !important;
}


@import url('https://fonts.googleapis.com/css2?family=Zen+Maru+Gothic:wght@400;500;700&display=swap');

body {
    font-family: 'Zen Maru Gothic', sans-serif !important;
}
h1, h2, h3 {
    font-family: 'Zen Maru Gothic', sans-serif !important;
    font-weight: 700;
}

@import url('https://fonts.googleapis.com/css2?family=Zen+Maru+Gothic:wght@400;500;700&display=swap');

/* サイト全体の背景色を #FAFAFA（ソフトホワイト）に */
body {
    background-color: #FAFAFA !important;
    color: #333333 !important; /* 本文の色をダークグレーに */
    font-family: 'Zen Maru Gothic', sans-serif !important;
}




/* 1165番のページだけ、テーマのヘッダー背景（グレーのエリア）を消す */
.page-id-1165 .entry-header, 
.page-id-1165 .page-header, 
.page-id-1165 .header-footer-group {
    display: none !important;
    height: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
}

/* グレーを消した後にできる「隙間」を埋める */
.page-id-1165 .site-content,
.page-id-1165 #content {
    padding-top: 0 !important;
    margin-top: 0 !important;
}

wp:postmeta.wp:meta_value:
/* h3 の吹き出し背景を黄色 (#f8e34d) にし、文字色をダークグレー (#333333) に */
h3 {
  position: relative;
  padding: 0.6em;
  background: #f8e34d !important;
  color: #333333 !important;
}

/* 吹き出しの三角部分の色を黄色 (#f8e34d) に */
h3:after {
  position: absolute;
  content: '';
  top: 100%;
  left: 30px;
  border: 15px solid transparent;
  border-top: 15px solid #f8e34d !important;
  width: 0;
  height: 0;
}

/* h4 のデザイン（背景色を #93d1f4 に変更） */
h4 {
  position: relative;
  padding: 5px 5px 5px 42px;
  background: #93d1f4 !important; /* ライトブルー */
  font-size: 20px;
  color: white !important; /* 文字色を白 */
  margin-left: -33px;
  line-height: 1.3;
  z-index: -1;
}

/* h4 の左側に三角形を追加 */
h4:before {
  position: absolute;
  content: '';
  left: -2px;
  top: -2px;
  border: none;
  border-left: solid 40px white; /* 三角形の色 */
  border-bottom: solid 79px transparent;
  z-index: -2;
}


h5 {
  position: relative;
  padding-left: 35px;
}
h5:before {
  position: absolute;
  font-family: "Font Awesome 5 Free";
  content: "\f0eb";
  background: #ffca2c;
  color: white;
  font-weight: 900;
  font-size: 15px;
  border-radius: 50%;
  left: 0;
  width: 25px;
  height: 25px;
  line-height: 25px;
  text-align: center;
  top: 50%;
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
}
h5:after {
  /*吹き出しのちょこんと出た部分*/
  content: '';
  display: block;
  position: absolute;
  left: 20px;
  height: 0;
  width: 0;
  border-top: 7px solid transparent;
  border-bottom: 7px solid transparent;
  border-left: 12px solid #ffca2c;
  top: 50%;
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
}

h6 {
  background: linear-gradient(transparent 70%, #a7d6ff 70%);
}

ul li {
  line-height: 1.5;
  padding: 0.5em 0 0.5em 1.5em;
  border-bottom: 2px solid white;
  list-style-type: none!important;
}

ul li:before {
  font-family: "Font Awesome 5 Free";
  content: "\f00c";/*アイコン種類*/
  position: absolute;
  left : 0.5em; /*左端からのアイコンまで*/
  color: #5f20ca; /*アイコン色*/
}

ul li:last-of-type {
  border-bottom: none;/*最後の線だけ消す*/
}

item.content:encoded:
お世話になっている皆さまへ

&nbsp;

7月以降のレッスンにつきまして、対面レッスンは無期限の休業、オンラインレッスンは8月31日までの休業延長とさせていただくことになりました。

&nbsp;

コロナに罹患した後も症状が続いており、当初は2〜3ヶ月での回復を目指していましたが、再び悪化してしまいました。現在も微熱や息苦しさ、倦怠感があり、長時間話すことが困難なため、オンラインレッスンも難しい状況です。医師の治療を受けていますが、まだ確立された治療法がないため、回復には時間がかかる見込みです。

&nbsp;

こうした状況から、皆さまをこれ以上お待たせするわけにはいかず、無期限の休業とオンラインレッスンの休業延長を決定いたしました。この決断に至るまで悩みましたが、ご理解いただければ幸いです。

&nbsp;

休業期間中も、何かご不明点やご相談がございましたら、いつでもお気軽にご連絡ください。

&nbsp;

代講の先生は現在調整中ですが、スケジュールの問題などで確約はできない状況です。個人的な目標としては、半年以内には全面復帰したいと考えています。

&nbsp;

この度は、多大なるご迷惑とご心配をおかけしてしまい、深くお詫び申し上げます。

